/* SmartLearn Native Color Classes */
.sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-text-emphasis { color: var(--smartlearn-text) !important; }
.sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-bg-main { background-color: var(--smartlearn-bg) !important; }
.sl-bg-card { background-color: var(--smartlearn-card-bg) !important; border: 1px solid var(--smartlearn-card-border) !important; }
.sl-bg-primary { background-color: var(--smartlearn-primary) !important; }
.sl-hero-path .sl-bg-primary-subtle { background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent) !important; }
.sl-hero-path .sl-btn-primary { background-color: var(--smartlearn-primary) !important; border-color: var(--smartlearn-primary) !important; color: #fff !important; }
.sl-hero-path .sl-btn-primary:hover { background-color: var(--smartlearn-primary-hover, var(--smartlearn-primary)) !important; filter: brightness(0.9); }
.sl-hero-path .sl-btn-outline-primary { border-color: var(--smartlearn-primary) !important; color: var(--smartlearn-primary) !important; }
.sl-hero-path .sl-btn-outline-primary:hover { background-color: var(--smartlearn-primary) !important; color: #fff !important; }
.sl-border-primary { border-color: var(--smartlearn-primary) !important; }
.sl-hero-path {
    min-height: 80vh;
}
.sl-hero-path .sl-path-title {
    letter-spacing: -0.03em;
}
.sl-hero-path .sl-node {
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    opacity: 0;
    transform: translateY(20px);
}
.sl-hero-path .sl-node:hover {
    transform: translateY(-5px) scale(1.02) !important;
    box-shadow: 0 15px 30px rgba(25, 135, 84, 0.15) !important;
    border-color: var(--smartlearn-primary) !important;
}

/* Animations */
.sl-hero-path .sl-node-1 { animation: slNodeFade 0.6s cubic-bezier(0.16, 1, 0.3, 1) 0.2s forwards; }
.sl-hero-path .sl-node-2 { animation: slNodeFade 0.6s cubic-bezier(0.16, 1, 0.3, 1) 0.6s forwards; }
.sl-hero-path .sl-node-3 { animation: slNodeFade 0.6s cubic-bezier(0.16, 1, 0.3, 1) 1.0s forwards; }

@keyframes slNodeFade {
    to { opacity: 1; transform: translateY(0); }
}

.sl-hero-path .sl-line-draw {
    stroke-dasharray: 1000;
    stroke-dashoffset: 1000;
    animation: slDash 3s linear forwards;
}

@keyframes slDash {
    to { stroke-dashoffset: 0; }
}

@media (max-width: 991px) {
    .sl-hero-path .sl-node { margin-left: 0 !important; max-width: 100% !important; }
}

